//! 🧬️ A native editor command transfers its sole mutation into one funded durable emission row.
use super::*;
use semio_plugin::retained_command::{ArtifactCommandWork,ArtifactCommandInputs,ArtifactCommandWorkStep};
use semio_framework_job::{StepContext,OriginalTurnFailure,OriginalConstructionAdmission,OriginalConstructionDemand,OriginalConstructionFailure,InteractiveJobCloseStep};
use semio_framework_value::{OriginalRetirementPoll,RetainedAllocationEffect,RetainedCloneProgress,RetainedCloneStep,RetainedWorkOutcome,RetainedWorkPoll,RetirementDemand,ValueError,ValueRefusalKind,retained_clone::RetainedCloneClose,retirement::RetireOwned};
use std::{mem::{size_of,ManuallyDrop}};
type App=EditorApp<EnergyModelEditor>;
type Output=Emit<EnergyModelMutation,EnergyModelConfigMutation,NoDraftMutation>;
pub(crate)struct EnergyModelCommandWork{bounded:BoundedArtifactCommandWork<App>,mutation:ManuallyDrop<Option<EnergyModelMutation>>,rows:ManuallyDrop<Option<Vec<EnergyModelMutation>>>,failure:ManuallyDrop<Option<OriginalConstructionFailure>>,retirement:RetainedCloneClose,construction:OriginalConstructionAdmission,unit:Option<()>,body:usize,native:bool,born:bool,consumed:bool,emitted:bool}
fn invalid()->ValueError{ValueError::literal(ValueRefusalKind::InvariantViolated,"original Energy mutation command ownership changed")}
fn construction(d:RetirementDemand)->OriginalConstructionDemand{OriginalConstructionDemand{items:1,copy_bytes:d.copy_bytes,capacity_bytes:d.capacity_bytes,release_bytes:d.release_bytes,depth:d.depth}}
fn receipt(d:RetirementDemand)->RetainedCloneProgress{RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,retained_capacity_bytes:d.capacity_bytes,released_bytes:d.release_bytes}}
fn actual<O>(result:&Result<(O,RetainedCloneProgress),ValueError>,reported:&mut Option<usize>){if let Ok((_,progress))=result{if progress.retained_capacity_bytes!=0&&reported.is_none(){*reported=Some(progress.retained_capacity_bytes)}}}
/// 🚨️ A constructor's own refusal is the failure the caller sees; its complete causes stay in the resident admission until closure retires them.
fn built<O>(cx:&mut StepContext<'_>,admission:&mut OriginalConstructionAdmission,output:&mut Option<O>,demand:OriginalConstructionDemand,construct:impl FnOnce()->Result<(O,RetainedCloneProgress),ValueError>)->Result<bool,OriginalTurnFailure>{let mut refused=None;let settled=semio_framework_job::admit_original_construction_settled(cx,admission,output,demand,1,|_,reported|{let result=construct();actual(&result,reported);if let Err(error)=&result{refused=Some(error.clone())}RetainedWorkOutcome{result,work:1}});match refused{Some(error)=>Err(error.into()),None=>settled}}
/// 🪜️ One bounded state change settles through the resident admission and its resident marker, so a pending turn never repeats the change.
fn stepped(cx:&mut StepContext<'_>,admission:&mut OriginalConstructionAdmission,marker:&mut Option<()>,demand:RetirementDemand,apply:impl FnOnce()->Result<(),ValueError>)->Result<bool,OriginalTurnFailure>{let settled=built(cx,admission,marker,construction(demand),||apply().map(|()|((),receipt(demand))))?;if settled{marker.take();}Ok(settled)}
fn settled(effect:&mut RetainedAllocationEffect<'_>,result:Result<RetainedCloneStep,ValueError>)->OriginalRetirementPoll{RetainedWorkPoll::Complete(RetainedWorkOutcome{result:result.map_err(Into::into),work:effect.performed_work()})}
fn begun<T:RetireOwned>(retirement:&mut RetainedCloneClose,value:&mut Option<T>,effect:&mut RetainedAllocationEffect<'_>)->OriginalRetirementPoll{let turn=retirement.begin_granted(value,effect);RetainedWorkPoll::Complete(RetainedWorkOutcome{result:turn.result.map(|step|step.unwrap_or(RetainedCloneStep::Progress(Default::default()))).map_err(Into::into),work:turn.work})}
impl EnergyModelCommandWork{pub(crate)fn new(tool:&'static str)->Self{Self{bounded:BoundedArtifactCommandWork::new(tool,energy_model_reduce,energy_model_extent),mutation:ManuallyDrop::new(None),rows:ManuallyDrop::new(None),failure:ManuallyDrop::new(None),retirement:Default::default(),construction:Default::default(),unit:None,body:0,native:false,born:false,consumed:false,emitted:false}}fn owned_is_empty(&self)->bool{self.mutation.is_none()&&self.rows.is_none()&&self.failure.is_none()&&self.retirement.is_empty()}fn close_quote(&self)->Result<RetirementDemand,ValueError>{if !self.retirement.is_empty(){return self.retirement.demands(self.body)}if self.failure.is_none()&&self.construction.has_failure(){return Ok(self.construction.take_failure_demand().physical())}if self.failure.is_some(){return self.retirement.next_owner_demands::<OriginalConstructionFailure>(true,&None,self.body)}if self.mutation.is_some(){return self.retirement.next_owner_demands::<EnergyModelMutation>(true,&None,self.body)}if self.rows.is_some(){return self.retirement.next_owner_demands::<Vec<EnergyModelMutation>>(true,&None,self.body)}Ok(Default::default())}}
impl ArtifactCommandWork<App> for EnergyModelCommandWork{
 fn tool_id(&self)->&'static str{self.bounded.tool_id}
 fn receive_original_command(&mut self,command:&mut EnergyModelEditorCommand,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{let EnergyModelEditorCommand::ApplyNativeMutation{mutation,..}=command else{return Ok(true)};if !self.construction.settling()&&(self.native||self.mutation.is_some()||mutation.is_none()){return Err(invalid().into())}let d=RetirementDemand{copy_bytes:2*size_of::<Option<EnergyModelMutation>>()+size_of::<(bool,usize)>(),depth:1,..Default::default()};let body=cx.retained_grant().maximum_copy_bytes;stepped(cx,&mut self.construction,&mut self.unit,d,||{*self.mutation=mutation.take();self.body=body;self.native=true;Ok(())})}
 fn extent(&self,command:&EnergyModelEditorCommand,snapshot:&EnergyModelSnapshot,interaction:&protocol::InteractionState,context:Option<&semio_plugin::app::ArtifactOwnedToolJobContext<App>>)->Option<usize>{self.bounded.extent(command,snapshot,interaction,context)}
 fn work_demands(&self,input:&ArtifactCommandInputs<'_,App>,body:usize)->Result<RetirementDemand,ValueError>{if !self.native{return self.bounded.work_demands(input,body)}if self.emitted{return Err(invalid())}if self.rows.is_none(){Ok(RetirementDemand{copy_bytes:size_of::<Option<Vec<EnergyModelMutation>>>(),capacity_bytes:size_of::<EnergyModelMutation>(),depth:1,..Default::default()})}else{Ok(RetirementDemand{copy_bytes:size_of::<EnergyModelMutation>()+size_of::<Option<Vec<EnergyModelMutation>>>()+size_of::<Output>()+size_of::<bool>(),depth:1,..Default::default()})}}
 fn step(&mut self,input:&ArtifactCommandInputs<'_,App>,cx:&mut StepContext<'_>)->Result<ArtifactCommandWorkStep<App>,OriginalTurnFailure>{if !self.native{return self.bounded.step(input,cx)}let d=self.work_demands(input,self.body)?;
  if !self.born{self.born=built(cx,&mut self.construction,&mut self.rows,construction(d),||{let mut rows=Vec::new();rows.try_reserve_exact(1).map_err(|_|ValueError::literal(ValueRefusalKind::AllocationFailed,"original Energy command row could not be reserved"))?;let mut p=receipt(d);p.retained_capacity_bytes=rows.capacity()*size_of::<EnergyModelMutation>();Ok((rows,p))})?;return Ok(ArtifactCommandWorkStep::Pending{stage:"energy-original-command-row",preview:&[]})}
  if !self.emitted{self.emitted=stepped(cx,&mut self.construction,&mut self.unit,d,||{let mutation=self.mutation.take().ok_or_else(invalid)?;self.rows.as_mut().ok_or_else(invalid)?.push(mutation);self.consumed=true;Ok(())})?;if !self.emitted{return Ok(ArtifactCommandWorkStep::Pending{stage:"energy-original-command-handoff",preview:&[]})}}
  Ok(ArtifactCommandWorkStep::Complete(Output::mutations(self.rows.take().ok_or_else(invalid)?)))}
 fn terminal_frame_release_bytes(&self)->Option<usize>{Some(size_of::<Self>())}
 fn reports_progress(&self)->bool{false}
 fn next_close_copy_byte_demand(&self)->Result<usize,ValueError>{Ok(self.close_quote()?.copy_bytes)}
 fn next_close_capacity_byte_demand(&self,_:usize)->Result<usize,ValueError>{Ok(self.close_quote()?.capacity_bytes)}
 fn next_close_release_byte_demand(&self)->Result<usize,ValueError>{Ok(self.close_quote()?.release_bytes)}
 fn next_close_depth_demand(&self)->Result<usize,ValueError>{Ok(self.close_quote()?.depth)}
 fn close_step(&mut self,cx:&mut StepContext<'_>)->Result<InteractiveJobCloseStep,OriginalTurnFailure>{
  if self.terminal_is_empty(){return Ok(InteractiveJobCloseStep::Complete{progress:Default::default()})}
  if self.failure.is_none()&&self.construction.has_failure(){self.construction.take_failure_into_step(&mut self.failure,cx)?;return Ok(InteractiveJobCloseStep::Pending{progress:Default::default()})}
  if self.owned_is_empty(){if !self.construction.terminal_is_empty(){self.construction.close_step(cx)?;}return Ok(if self.terminal_is_empty(){InteractiveJobCloseStep::Complete{progress:Default::default()}}else{InteractiveJobCloseStep::Pending{progress:Default::default()}})}
  let d=self.close_quote()?;let body=self.body;
  let step=semio_framework_job::close_original_effect_step(cx,d,|effect|{if !self.retirement.is_empty(){return self.retirement.step_granted(body,effect)}if self.failure.is_some(){return begun(&mut self.retirement,&mut self.failure,effect)}if self.mutation.is_some(){return begun(&mut self.retirement,&mut self.mutation,effect)}if self.rows.is_some(){return begun(&mut self.retirement,&mut self.rows,effect)}settled(effect,Ok(RetainedCloneStep::Complete(Default::default())))})?;
  let progress=step.progress();
  Ok(if self.terminal_is_empty(){InteractiveJobCloseStep::Complete{progress}}else{InteractiveJobCloseStep::Pending{progress}})
 }
 fn terminal_is_empty(&self)->bool{self.owned_is_empty()&&self.construction.terminal_is_empty()}
}
impl Drop for EnergyModelCommandWork{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"original Energy command work requires funded closure")}}

